// ==UserScript==
// @name         Prediksi Bubble - 53 Pasaran
// @namespace    local.prediksi.bubble
// @version      1.4.0
// @description  Generator angka acak, panel kecil, salin per pasaran atau semua. Bukan ramalan hasil undian.
// @match        https://my.livechatinc.com/*
// @run-at       document-idle
// @noframes
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_setClipboard
// ==/UserScript==

/* CARA PASANG:
   Tampermonkey > Create a new script > hapus isi bawaan > tempel seluruh file
   ini > Ctrl+S > muat ulang https://my.livechatinc.com/.
   Klik bubble bintang di kanan bawah. Pilih tanggal (default WIB), pasaran,
   lalu Generate satu / Generate semua. Salin hanya menyalin ke clipboard.
   Hasil dan edit manual disimpan per tanggal, maksimal 14 tanggal terakhir.
   Semua angka acak; tidak menggunakan data hasil undian atau membaca chat.
*/
(() => {
  'use strict';
  if (document.getElementById('prediksi-bubble-local')) return;
  // Urutan pasaran tetap; tiga shio berbeda dipilih acak saat generate.
  const MARKETS = [
  "TOTO MACAU PAGI",
  "KENTUCKY MIDDAY",
  "FLORIDA MIDDAY",
  "HUAHIN 0100",
  "BANGKOK 0130",
  "NEW YORK MIDDAY",
  "NORTH CAROLINA DAY",
  "BRUNEI 02",
  "OREGON 03",
  "OREGON 06",
  "CALIFORNIA",
  "FLORIDA EVENING",
  "OREGON 09",
  "BANGKOK 0930",
  "NEW YORK EVENING",
  "KENTUCKY EVENING",
  "CAROLINA EVENING",
  "TOTO CAMBODIA",
  "CHELSEA 11",
  "OREGON 12",
  "BULLSEYE",
  "POIPET 12",
  "TOTO MACAU SIANG",
  "SYDNEY",
  "JAKARTA 1400",
  "BRUNEI 14",
  "CHELSEA 15",
  "TOTO MACAU 5D SORE",
  "POIPET 15",
  "TOTO MALI 1530",
  "TOTO MACAU SORE",
  "HUAHIN 1630",
  "KINGKONG 4D SORE",
  "SINGAPORE",
  "MAGNUM4D",
  "CHELSEA 19",
  "TOTO MACAU MALAM I",
  "POIPET 19",
  "PCSO",
  "TOTO MALI 2030",
  "HUAHIN 2100",
  "CHELSEA 21",
  "TOTO MACAU 5D MALAM",
  "NEVADA",
  "BRUNEI 21",
  "TOTO MACAU MALAM II",
  "POIPET 22",
  "HONGKONG",
  "TOTO MALI 2330",
  "JAKARTA 2330",
  "KINGKONG 4D MALAM",
  "TOTO MACAU MALAM III",
  "HOKI DRAW"
];
  const SHIO = ["TIKUS","KERBAU","HARIMAU","KELINCI","NAGA","ULAR","KUDA","KAMBING","MONYET","AYAM","ANJING","BABI"];
  const KEY = 'prediksi-bubble-v1';
  const today = () => {
    const p = new Intl.DateTimeFormat('en-GB', {timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
    const get = t => p.find(x => x.type === t).value;
    return `${get('year')}-${get('month')}-${get('day')}`;
  };
  function random(n) {
    const a = new Uint32Array(1), limit = Math.floor(4294967296 / n) * n;
    do { crypto.getRandomValues(a); } while (a[0] >= limit);
    return a[0] % n;
  }
  const digits = n => Array.from({length:n}, () => random(10)).join('');
  function unique(count, factory) {
    const set = new Set();
    while (set.size < count) set.add(factory());
    return [...set];
  }
  function generate(market, iso) {
    const date = new Date(`${iso}T12:00:00+07:00`);
    const weekday = new Intl.DateTimeFormat('id-ID',{weekday:'long',timeZone:'Asia/Jakarta'}).format(date);
    const label = new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'long',year:'numeric',timeZone:'Asia/Jakarta'}).format(date);
    const lines = [`Prediksi ${market}`, `Hari ${weekday} , ${label}`, `BBFS : ${digits(7)}`, `AM/AI/CK : ${digits(5)}`];
    if (market.includes('5D')) lines.push(`5D : ${digits(5)}`);
    lines.push(`4D : ${unique(4,()=>digits(4)).join(' ')}`, `3D : ${unique(4,()=>digits(3)).join(' ')}`,
      `2D (BB) : ${unique(10,()=>digits(2)).join(' ')}`,
      `COLOK BEBAS : ${unique(2,()=>digits(1)).join(' / ')}`,
      `COLOK BEBAS 2D : ${unique(3,()=>digits(2)).join(' / ')}`,
      `TWIN : ${unique(3,()=>{const d=digits(1);return d+d;}).join(' / ')}`,
      `SHIO : ${unique(3,()=>SHIO[random(SHIO.length)]).join(' / ')}`,
      'Selalu Utamakan Prediksi Sendiri');
    return lines.join('\n');
  }
  let state;
  try { state = JSON.parse(GM_getValue(KEY, '{}')); } catch { state = {}; }
  if (!state || typeof state !== 'object' || Array.isArray(state)) state = {};
  state.days = state.days && typeof state.days === 'object' && !Array.isArray(state.days) ? state.days : {};
  // Sesuaikan hasil tersimpan tanpa mengubah angka sebelumnya.
  for (const day of Object.values(state.days)) {
    if (!day || typeof day !== 'object') continue;
    if (typeof day.HOKIDRAW === 'string' && !day['HOKI DRAW']) day['HOKI DRAW'] = day.HOKIDRAW;
    delete day.HOKIDRAW;
    for (const market of MARKETS) {
      if (typeof day[market] !== 'string') continue;
      day[market] = day[market].replace(/^Prediksi HOKIDRAW$/m, 'Prediksi HOKI DRAW')
        .replace(/\bMACAN\b/g, 'HARIMAU');
    }
  }
  if (state.selected === 'HOKIDRAW') state.selected = 'HOKI DRAW';
  const host = document.createElement('div');
  host.id = 'prediksi-bubble-local';
  host.style.cssText = 'position:fixed;right:16px;bottom:80px;z-index:2147483647';
  document.body.append(host);
  const root = host.attachShadow({mode:'open'});
  const THEME_IMAGE = 'data:image/png;base64,';
  const sparkle = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="m20 2 .6 1.4L22 4l-1.4.6L20 6l-.6-1.4L18 4l1.4-.6L20 2Z" fill="currentColor"/></svg>';
  root.innerHTML = `<style>
    :host{font:13px/1.5 system-ui,-apple-system,sans-serif;color:#f5f1f2;color-scheme:dark}*{box-sizing:border-box}
    button,input,select,textarea{font:inherit}button{cursor:pointer;border:1px solid #363039;border-radius:11px;background:#211d23;color:#dfd7df;padding:10px 8px;font-weight:650;transition:background .18s,transform .18s,box-shadow .18s}button:hover{background:#34232b;border-color:#75404e}button:active{transform:scale(.97)}button:disabled{opacity:.45;cursor:default}
    button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid #ff6b85;outline-offset:2px}svg{width:24px;height:24px;display:block}
    #bubble{position:relative;display:grid;place-items:center;width:55px;height:55px;border:1px solid #f9526877;border-radius:19px;background:radial-gradient(circle at 25% 10%,#6c2638,transparent 65%),linear-gradient(145deg,#2c1822,#100e12);color:#ff647d;box-shadow:0 9px 30px #0008,0 0 19px #e532452b,inset 0 1px 0 #ffb1be26}
    #bubble svg{width:29px;height:29px;filter:drop-shadow(0 0 6px #ff476577)}#bubble:hover{transform:translateY(-3px);border-color:#ff637c;box-shadow:0 12px 35px #0009,0 0 25px #e5324540}#bubble::after{content:'';position:absolute;right:7px;top:7px;width:5px;height:5px;border-radius:50%;background:#ff536d;box-shadow:0 0 7px #ff536d}
    #panel{position:absolute;right:0;bottom:69px;width:365px;max-width:calc(100vw - 32px);max-height:calc(100dvh - 165px);overflow:auto;background:#141216;border:1px solid #443039;border-radius:23px;box-shadow:0 24px 75px #0009,0 0 30px #a51a2e14;animation:enter .2s ease-out;scrollbar-width:thin;scrollbar-color:#58343e #141216}
    [hidden]{display:none!important}@keyframes enter{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
    header{position:relative;display:flex;align-items:center;gap:11px;padding:19px 18px 18px;background:radial-gradient(ellipse at top right,#671b304d,transparent 75%),linear-gradient(135deg,#20171f,#161217);border-bottom:1px solid #442532}
    header::before{content:'';position:absolute;top:0;left:22px;right:22px;height:2px;background:linear-gradient(90deg,transparent,#fa4568,transparent)}
    .brand{display:grid;place-items:center;width:39px;height:39px;border:1px solid #793142;border-radius:13px;background:linear-gradient(135deg,#51232f,#25171f);color:#ff738b;box-shadow:0 4px 15px #0003}
    .heading{flex:1}.eyebrow{font-size:9px;letter-spacing:2.5px;color:#ef6b82;font-weight:750}.heading strong{display:block;margin-top:2px;font-size:18px;letter-spacing:-.5px;color:#fff1f4}#close{display:grid;place-items:center;width:28px;height:28px;padding:0;background:#ffffff06;border:1px solid #ffffff0c;border-radius:9px;font-size:20px;color:#ae8d98}
    .body{padding:15px 17px 16px}.summary{display:flex;align-items:center;justify-content:space-between;font-size:10px;color:#b298a4;margin-bottom:13px}.badge{border:1px solid #6d2b3c;border-radius:20px;background:#321b25;padding:3px 9px;color:#ff98ac;font-weight:650}
    label{display:block;margin-top:11px;font-size:10px;font-weight:700;color:#bea6b1;letter-spacing:.6px}input,select{width:100%;padding:9px 10px;margin-top:5px;background:#1d191f;color:#f0e7ed;border:1px solid #39303a;border-radius:10px;min-height:38px}input:hover,select:hover{border-color:#67414e}input::placeholder{color:#99818e}input[type=date]{font-size:12px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:9px}.fields label{margin:0}
    textarea{width:100%;height:240px;resize:vertical;min-height:110px;padding:12px;background:linear-gradient(145deg,#100f12,#171218);color:#e6d8e0;border:1px solid #3d2935;border-radius:12px;font:11px/1.85 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre;margin-top:8px;scrollbar-width:thin;scrollbar-color:#633241 #141216;box-shadow:inset 0 2px 8px #0003}textarea::placeholder{color:#947e8b}
    .result-label{display:flex;align-items:center;justify-content:space-between;margin-top:17px}.result-label label{margin:0;color:#efbbc8}.result-label span{color:#aa909e;font-size:9px}
    .row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}.primary{background:linear-gradient(120deg,#e53b58,#b92343);border-color:#ee4e69;color:#fff;box-shadow:0 4px 16px #ce254333}.primary:hover{background:linear-gradient(120deg,#f04a66,#cc3152);border-color:#ff7b90}.copy{background:#3c1d2a;border-color:#7d3047;color:#ffb6c8}
    #viewOne,#viewAll{font-size:10px;padding:6px;border-radius:8px}#status{min-height:30px;font-size:10px;color:#ccb4c0;margin-top:10px;padding:8px 10px;background:#211820;border:1px solid #35232e;border-radius:9px}.note{margin:11px 0 0;text-align:center;color:#a58998;font-size:9px}
    @media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}@media(max-height:600px){textarea{height:140px}header{padding:12px 18px}.body{padding-top:10px}}
    #panel{position:fixed;right:auto;bottom:auto;max-height:calc(100dvh - 24px);background:linear-gradient(#080808c9,#080808eb),url("${THEME_IMAGE}") center/cover;border:1px solid #a83b3b;border-radius:16px;box-shadow:0 20px 65px #000b,0 0 20px #ff000022}
    header{min-height:123px;align-items:flex-start;background:linear-gradient(transparent 60%,#080808),url("${THEME_IMAGE}") center top/100% auto;border-bottom:1px solid #9b2020}
    .brand,.heading{display:none}#close{margin-left:auto;background:#080808cc;color:#fff;border-color:#b63030}
    .body{background:#080808a6}input,select,textarea{background:#0c0c0cf2;color:#eee;border-color:#503030}
    .primary{background:linear-gradient(125deg,#e82020,#940c0c);border-color:#ff4141}.primary:hover{background:linear-gradient(125deg,#ff3030,#b01616)}.copy{background:#361010;border-color:#892828;color:#ffc4c4}
    .badge{background:#2d0c0c;border-color:#872525;color:#ffa8a8}#status{background:#170b0be8;border-color:#482525}button:hover{border-color:#bd3737}
    #bubble{width:68px;height:68px;border-radius:18px;touch-action:none;user-select:none;cursor:grab;overflow:hidden;border:1px solid #e53939;background:#080808 url("${THEME_IMAGE}") center top/auto 100%;box-shadow:0 7px 25px #000a,0 0 14px #e0000055}
    #bubble:hover{transform:none;border-color:#ff7777}#bubble:active{transform:none;cursor:grabbing}#bubble::after{display:none}
    #bubble img{display:block;width:100%;height:100%;object-fit:cover;object-position:center top;pointer-events:none}#bubble.dragging{cursor:grabbing;box-shadow:0 12px 30px #000a,0 0 24px #ff000066}
  </style>
  <section id="panel" aria-label="Generator angka" hidden>
    <header><div class="brand">${sparkle}</div><div class="heading"><div class="eyebrow">CRIMSON STUDIO</div><strong>Prediksi Pasaran</strong></div><button id="close" aria-label="Tutup">×</button></header>
    <div class="body">
      <div class="summary"><span class="badge">53 pasaran tersedia</span><span>Tersimpan otomatis</span></div>
      <div class="fields"><label>TANGGAL · WIB<input id="date" type="date"></label><label>CARI PASARAN<input id="search" type="search" placeholder="Nama pasaran…"></label></div>
      <label>PILIH PASARAN<select id="market"></select></label>
      <div class="row"><button id="one">↻ Generate satu</button><button id="all" class="primary">✧ Generate semua</button></div>
      <div class="result-label"><label for="output">HASIL PREDIKSI</label><span id="viewHint">Bisa diedit langsung</span></div>
      <div class="row"><button id="viewOne">Lihat satu</button><button id="viewAll">Lihat semua</button></div>
      <textarea id="output" spellcheck="false" placeholder="Pilih pasaran, lalu klik generate.&#10;Hasil Anda akan muncul di sini."></textarea>
      <div class="row"><button id="copy" class="copy">Salin pasaran ini</button><button id="copyAll">Salin semua</button></div>
      <div id="status" role="status" aria-live="polite"></div>
      <p class="note">Angka acak · Bukan ramalan hasil undian</p>
    </div>
  </section>
  <button id="bubble" title="Klik untuk buka · Geser untuk pindahkan" aria-label="Buka generator angka" aria-expanded="false"><img src="${THEME_IMAGE}" alt="Prediksi Line" draggable="false"></button>`;
  const $ = id => root.getElementById(id);
  $('date').value = today();
  let selected = MARKETS.includes(state.selected) ? state.selected : 'SINGAPORE';
  let viewAll = false;
  const validDate = () => /^\d{4}-\d{2}-\d{2}$/.test($('date').value) && Number.isFinite(Date.parse($('date').value));
  function records() {
    const key = $('date').value;
    if (!state.days[key] || typeof state.days[key] !== 'object') state.days[key] = {};
    return state.days[key];
  }
  function save() {
    state.selected = selected;
    const keys = Object.keys(state.days).sort();
    while(keys.length > 14) {
      const index = keys.findIndex(k => k !== $('date').value);
      delete state.days[keys.splice(index,1)[0]];
    }
    try { GM_setValue(KEY, JSON.stringify(state)); return true; }
    catch { $('status').textContent='Hasil tersedia, tetapi penyimpanan gagal. Salin sebelum menutup.'; return false; }
  }
  function display() {
    const data = validDate() ? records() : {};
    $('output').value = viewAll ? MARKETS.map(m=>data[m]).filter(t=>typeof t==='string' && t.trim()).join('\n\n') : (data[selected] || '');
    $('output').readOnly = viewAll;
    $('viewHint').textContent = viewAll ? 'Semua pasaran · sesuai urutan' : 'Bisa diedit langsung';
    $('viewOne').setAttribute('aria-pressed', String(!viewAll));
    $('viewAll').setAttribute('aria-pressed', String(viewAll));
    $('viewOne').classList.toggle('copy', !viewAll);
    $('viewAll').classList.toggle('copy', viewAll);
    const count = validDate() ? MARKETS.filter(m=>typeof records()[m]==='string' && records()[m].trim()).length : 0;
    $('status').textContent = validDate() ? `${count}/${MARKETS.length} pasaran tersedia untuk tanggal ini.` : 'Pilih tanggal yang valid.';
  }
  function options() {
    const query = $('search').value.trim().toUpperCase();
    const list = MARKETS.filter(m=>m.includes(query));
    $('market').replaceChildren(...list.map(m=>{const o=document.createElement('option');o.value=m;o.textContent=m;return o;}));
    if(list.length && !list.includes(selected)) selected=list[0];
    $('market').value=selected;
    $('one').disabled=$('copy').disabled=!list.length;
    display();
    if(!list.length) { $('output').value=''; $('status').textContent='Pasaran tidak ditemukan.'; }
  }
  function open(value) {
    $('panel').hidden=!value;
    $('bubble').setAttribute('aria-expanded',String(value));
    if(value) {placePanel();$('search').focus();} else $('bubble').focus();
  }
  const POSITION_KEY = 'prediksi-bubble-position-v1';
  const clamp = (v,min,max) => Math.max(min,Math.min(v,Math.max(min,max)));
  let position;
  try {position=JSON.parse(GM_getValue(POSITION_KEY,'null'));} catch {position=null;}
  function placePanel() {
    if ($('panel').hidden) return;
    const rect=host.getBoundingClientRect(), panel=$('panel');
    const width=panel.offsetWidth, height=panel.offsetHeight;
    const x=clamp(rect.right-width,12,window.innerWidth-width-12);
    const above=rect.top-height-10;
    const y=above>=12 ? above : clamp(rect.bottom+10,12,window.innerHeight-height-12);
    panel.style.left=x+'px'; panel.style.top=y+'px';
  }
  function moveBubble(x,y) {
    const size=$('bubble').offsetWidth || 68;
    position={x:clamp(x,8,window.innerWidth-size-8),y:clamp(y,8,window.innerHeight-size-8)};
    host.style.right='auto';host.style.bottom='auto';
    host.style.left=position.x+'px';host.style.top=position.y+'px';
    placePanel();
  }
  function rememberPosition() {try{GM_setValue(POSITION_KEY,JSON.stringify(position));}catch{}}
  if(position && Number.isFinite(position.x) && Number.isFinite(position.y)) moveBubble(position.x,position.y);
  else moveBubble(window.innerWidth-84,window.innerHeight-148);
  let drag=null, suppressClick=false;
  $('bubble').addEventListener('pointerdown',e=>{
    if(!e.isPrimary || e.button!==0)return;
    suppressClick=false;
    drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:position.x,startY:position.y,moved:false};
    $('bubble').setPointerCapture(e.pointerId);
  });
  $('bubble').addEventListener('pointermove',e=>{
    if(!drag || e.pointerId!==drag.id)return;
    const dx=e.clientX-drag.x,dy=e.clientY-drag.y;
    if(!drag.moved && Math.hypot(dx,dy)<5)return;
    drag.moved=true;suppressClick=true;
    $('bubble').classList.add('dragging');
    moveBubble(drag.startX+dx,drag.startY+dy);
  });
  function finishDrag(e) {
    if(!drag || e.pointerId!==drag.id)return;
    if(drag.moved) rememberPosition();
    drag=null;$('bubble').classList.remove('dragging');
  }
  $('bubble').addEventListener('pointerup',finishDrag);
  $('bubble').addEventListener('pointercancel',finishDrag);
  $('bubble').addEventListener('lostpointercapture',finishDrag);
  $('bubble').onclick=e=>{
    if(suppressClick && e.detail!==0){suppressClick=false;return;}
    suppressClick=false;open($('panel').hidden);
  };
  window.addEventListener('resize',()=>{moveBubble(position.x,position.y);rememberPosition();});
  new ResizeObserver(placePanel).observe($('panel'));
  $('close').onclick=()=>open(false);
  root.addEventListener('keydown',e=>{if(e.key==='Escape')open(false);});
  $('search').oninput=()=>{viewAll=false;options();};
  $('viewOne').onclick=()=>{viewAll=false;display();};
  $('viewAll').onclick=()=>{viewAll=true;display();};
  $('market').onchange=()=>{selected=$('market').value;viewAll=false;display();save();};
  $('date').onchange=display;
  $('output').oninput=()=>{if(!viewAll && validDate() && $('market').value){records()[selected]=$('output').value;save();}};
  function run(all) {
    if(!validDate()) {display();return;}
    const list=all?MARKETS:[selected];

    for(const m of list) records()[m]=generate(m,$('date').value);
    viewAll=all;
    display();
    if(save()) $('status').textContent=`${list.length} pasaran berhasil dibuat dan disimpan.`;
  }
  $('one').onclick=()=>run(false);
  $('all').onclick=()=>run(true);
  function copy(all) {
    if(!validDate()){display();return;}
    const list=all?MARKETS:[selected];
    const texts=list.map(m=>records()[m]).filter(t=>typeof t==='string' && t.trim());
    if(!texts.length){$('status').textContent='Generate hasil terlebih dahulu.';return;}
    if(all && texts.length!==MARKETS.length){$('status').textContent='Klik Generate semua terlebih dahulu agar 53 pasaran lengkap.';return;}
    try {
      GM_setClipboard(texts.join('\n\n'),'text',()=>{$('status').textContent=`${texts.length} pasaran berhasil disalin.`;});
    } catch { viewAll=all;display();$('output').focus();$('output').select();$('status').textContent='Clipboard gagal. Salin hasil terpilih dengan Ctrl+C.'; }
  }
  $('copy').onclick=()=>copy(false);
  $('copyAll').onclick=()=>copy(true);
  options();
  save();
})();
